function changed(){dirty=true;$('#sceneTitle').textContent=PRESETS[preset].name+' · 自定义';stopPlay();}
function select(id){selected=id;rightTab='detail';detail();updateSelection();}
function moveItem(id,patch){const a=items.find(x=>x.id===id);if(!a)return;if(Object.values(patch).some(v=>!Number.isFinite(v))){toast('请输入有效格坐标');detail();return;}const next={...a,...patch};for(const k of ['gx','gy','gz'])next[k]=Math.round(next[k]);if(!valid(next)||conflict(next,items)){toast('超出网格或占位重叠：请换一个位置');detail();return;}Object.assign(a,next);changed();detail();}
function addItem(type,gx=23,gy=26,gz=0,from=null,exact=false){if(!M[type])return;const candidate=clampPosition({...from,id:'new',type,gx,gy,gz,state:from?.state||0,color:from?.color||'#3158e8',intensity:from?.intensity||65,temperature:from?.temperature||3200});const free=exact?(!conflict(candidate,items)?candidate:null):findSpace(type,items,gx,gy,gz,from||{});if(!free){toast('此层没有可用位置，请调整坐标或移除模块');return;}const a={...free,id:'u'+uid++};items.push(a);buildModule(a);changed();select(a.id);toast('已添加'+M[type].name+' · '+M[type].cells.join(' × ')+' 格');}
function exportConfig(){const d={project:'邮轮72变',version:'grid48-1',wall_mm:[2900,2900],grid:{unit_mm:48,counts:GRID,origin_wall_mm:[10,10,0],axes:['左右','上下','离墙']},scene:PRESETS[preset].name,modified:dirty,warning:'整数格为占位与布局规则，材料厚度可小于一格。48mm背部适配系统、离墙叠放及承载待工程验证。',modules:items.map(a=>({...a,name:M[a.type].name,position_cells:[a.gx,a.gy,a.gz],position_grid_mm:[a.gx,a.gy,a.gz].map(v=>v*48),size_cells:M[a.type].cells,dimensions_mm:M[a.type].cells.map(v=>v*48),reserved_cells:cells(a),interface:M[a.type].anchor,standard_parts:M[a.type].parts}))};const url=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));download(url,'邮轮72变_48mm网格配置.json');setTimeout(()=>URL.revokeObjectURL(url),1000);toast('格坐标、占位和功能清单已导出');}
