function setPreset(i){preset=i;dirty=false;night=PRESETS[i].ambient==='night';for(const g of models.values())dispose(g);models.clear();items=clone(PRESETS[i].items);selected=items[0]?.id;for(const a of items)buildModule(a,true);$('#sceneTitle').textContent=PRESETS[i].name;$('#sceneDesc').textContent=PRESETS[i].desc;$$('[data-scene]').forEach(b=>b.classList.toggle('active',+b.dataset.scene===i));detail();updateSelection();}
