 canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;get(e);const hit=ray.intersectObjects([...models.values()],true)[0];if(!hit)return;const a=items.find(x=>x.id===hit.object.userData.itemId);if(!a)return;select(a.id);plane.constant=-a.gz*PITCH;const start=point(e);if(!start)return;drag={id:a.id,start,a:{...a},px:e.clientX,py:e.clientY,moved:false,blocked:false};orbit.enabled=false;canvas.setPointerCapture(e.pointerId);});
