 const release=()=>{if(drag?.moved){changed();detail();}if(drag?.blocked)toast('该位置超界或重叠，保留上一个可用格位');drag=null;orbit.enabled=true;selectionBox.material.color.set('#3158e8');};canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);
